   5: /* I2: copy one stream to standard output byte for byte. */
   6: static int copy(FILE *in, const char *path) {
   7:     int c;
   8:     while ((c = getc(in)) != EOF) putchar(c);
   9:     if (ferror(in)) { error_path("cannot read", path); return -1; }
  10:     return 0;
  11: }
  12: 
  13: /* I2, C1: files in order; no operands or "-" means standard input. */
  14: int main(int argc, char **argv) {
  15:     init_program(argv[0]);
  16:     int failed = 0;
  17:     for (int i = 1; i < argc || i == 1; ++i) {
  18:         const char *path = i < argc ? argv[i] : "-";
  19:         FILE *in = strcmp(path, "-") ? fopen(path, "rb") : stdin;
  20:         if (!in) { error_path("cannot open", path); failed = 1; continue; }
  21:         if (copy(in, path) < 0) failed = 1;
  22:         if (in != stdin) fclose(in);
  23:     }
  24:     if (fflush(stdout) == EOF) { error_path("cannot write", "standard output"); failed = 1; }
  25:     return failed;
  26: }
