FILE find.c
   1: #include "common.h"
   2: #include <dirent.h>
   3: #include <errno.h>
   4: #include <fnmatch.h>
   5: #include <stdio.h>
   6: #include <stdlib.h>
   7: #include <string.h>
   8: 
   9: static const char *name_glob; /* -name GLOB, NULL = any name */
  10: static char type;             /* -type f|d, 0 = any type */
  11: static int failed;
  12: 
  13: /* I6: does PATH pass every test given on the command line? */
  14: static bool matches(const char *path, const struct stat *st) {
  15:     if (name_glob && fnmatch(name_glob, base_name(path), 0) != 0) return false;
  16:     if (type == 'f') return S_ISREG(st->st_mode);
  17:     if (type == 'd') return S_ISDIR(st->st_mode);
  18:     return true;
  19: }
  20: 
  21: /* I6: print PATH if it matches, then walk into it; lstat so links are never followed. */
  22: static void walk(const char *path) {
  23:     struct stat st;
  24:     if (lstat(path, &st) < 0) { error_path("cannot stat", path); failed = 1; return; }
  25:     if (matches(path, &st)) puts(path);
  26:     if (!S_ISDIR(st.st_mode)) return;
  27:     DIR *dir = opendir(path);
  28:     if (!dir) { error_path("cannot open directory", path); failed = 1; return; }
  29:     struct dirent *entry;
  30:     while ((errno = 0, entry = readdir(dir))) {
  31:         if (!strcmp(entry->d_name, ".") || !strcmp(entry->d_name, "..")) continue;
  32:         char *child = join_path(path, entry->d_name);
  33:         walk(child);
  34:         free(child);
  35:     }
  36:     if (errno) { error_path("cannot read directory", path); failed = 1; }
  37:     closedir(dir);
  38: }
  39: 
  40: /* I6, C1: [PATH...] (default ".") then -name GLOB and/or -type f|d. */
  41: int main(int argc, char **argv) {
  42:     init_program(argv[0]);
  43:     int end = 1;
  44:     while (end < argc && argv[end][0] != '-') ++end;
  45:     for (int i = end; i < argc; i += 2) {
  46:         const char *value = i + 1 < argc ? argv[i + 1] : NULL;
  47:         if (value && !strcmp(argv[i], "-name")) name_glob = value;
  48:         else if (value && !strcmp(argv[i], "-type") && (!strcmp(value, "f") || !strcmp(value, "d"))) type = *value;
  49:         else { fprintf(stderr, "%s: invalid expression at '%s'\n", program, argv[i]); return 1; }
  50:     }
  51:     if (end == 1) walk(".");
  52:     for (int i = 1; i < end; ++i) {
  53:         char *path = clean_path(argv[i]);
  54:         walk(path);
  55:         free(path);
  56:     }
  57:     if (fflush(stdout) == EOF) { error_path("cannot write", "standard output"); failed = 1; }
  58:     return failed;
  59: }
