FILE mkdir.c
   1: #include "common.h"
   2: #include <errno.h>
   3: #include <stdio.h>
   4: #include <stdlib.h>
   5: #include <string.h>
   6: #include <unistd.h>
   7: 
   8: /* I3: create one directory; with -p an existing directory is accepted (a file is not). */
   9: static int create(const char *path, mode_t mode, bool parents) {
  10:     if (mkdir(path, mode) == 0) return 0;
  11:     if (parents && errno == EEXIST) {
  12:         struct stat st;
  13:         if (stat(path, &st) == 0 && S_ISDIR(st.st_mode)) return 0;
  14:         errno = EEXIST;
  15:     }
  16:     error_path("cannot create directory", path);
  17:     return -1;
  18: }
  19: 
  20: /* I3, C1, C2: [-p] DIR...; -p creates each missing parent first. */
  21: int main(int argc, char **argv) {
  22:     init_program(argv[0]);
  23:     bool parents = false;
  24:     mode_t mask = umask(0); umask(mask);
  25:     int ch;
  26:     while ((ch = getopt(argc, argv, "p")) != -1) {
  27:         if (ch != 'p') { printf("Usage: %s [-p] DIRECTORY...\n", program); return 1; }
  28:         parents = true;
  29:     }
  30:     if (optind == argc) { printf("Usage: %s [-p] DIRECTORY...\n", program); return 1; }
  31:     int failed = 0;
  32:     for (int i = optind; i < argc; ++i) {
  33:         char *path = clean_path(argv[i]);
  34:         bool ok = true;
  35:         /* -p: create "a", then "a/b", ... ("a//b" just meets "a" twice, which -p accepts) */
  36:         for (char *p = strchr(path + 1, '/'); parents && ok && p; p = strchr(p + 1, '/')) {
  37:             *p = '\0';
  38:             /* Parent directories must remain traversable even under a restrictive umask. */
  39:             mode_t previous = umask(0);
  40:             ok = create(path, (0777 & ~mask) | S_IWUSR | S_IXUSR, true) == 0;
  41:             umask(previous);
  42:             *p = '/';
  43:         }
  44:         if (!ok || create(path, 0777 & ~mask, parents) < 0) failed = 1;
  45:         free(path);
  46:     }
  47:     return failed;
  48: }
FILE mv.c
   1: #include "common.h"
   2: #include <stdio.h>
   3: #include <stdlib.h>
   4: 
   5: /* I4, C1, C2: SRC DST renames (replacing a file DST); SRC... DIR moves into DIR. */
   6: int main(int argc, char **argv) {
   7:     init_program(argv[0]);
   8:     if (argc < 3) { printf("Usage: %s SOURCE... DESTINATION\n", program); return 1; }
   9:     char *destination = clean_path(argv[argc - 1]);
  10:     struct stat st;
  11:     bool into_dir = stat(destination, &st) == 0 && S_ISDIR(st.st_mode);
  12:     if (argc > 3 && !into_dir) {
  13:         fprintf(stderr, "%s: destination must be a directory\n", program); free(destination); return 1;
  14:     }
  15:     int failed = 0;
  16:     for (int i = 1; i < argc - 1; ++i) {
  17:         char *source = clean_path(argv[i]);
  18:         char *target = into_dir ? join_path(destination, base_name(source)) : xstrdup(destination);
  19:         /* cross-device moves fail here with EXDEV: copying is a non-goal */
  20:         if (rename(source, target) < 0) { error_path("cannot move to", target); failed = 1; }
  21:         free(source); free(target);
  22:     }
  23:     free(destination);
  24:     return failed;
  25: }
FILE rm.c
   1: #include "common.h"
   2: #include <dirent.h>
   3: #include <errno.h>
   4: #include <stdio.h>
   5: #include <stdlib.h>
   6: #include <string.h>
   7: #include <unistd.h>
   8: 
   9: /* I5: remove PATH; a directory only when recursive; lstat so links are removed, never followed. */
  10: static int remove_tree(const char *path, bool recursive, bool force) {
  11:     struct stat st;
  12:     if (lstat(path, &st) < 0) {
  13:         if (force && errno == ENOENT) return 0;
  14:         error_path("cannot access", path); return -1;
  15:     }
  16:     if (S_ISDIR(st.st_mode)) {
  17:         if (!recursive) { errno = EISDIR; error_path("cannot remove", path); return -1; }
  18:         DIR *dir = opendir(path);
  19:         if (!dir) { error_path("cannot open directory", path); return -1; }
  20:         int failed = 0;
  21:         struct dirent *entry;
  22:         while ((errno = 0, entry = readdir(dir))) {
  23:             if (!strcmp(entry->d_name, ".") || !strcmp(entry->d_name, "..")) continue;
  24:             char *child = join_path(path, entry->d_name);
  25:             if (remove_tree(child, true, force) < 0) failed = 1;
  26:             free(child);
  27:         }
  28:         if (errno) { error_path("cannot read directory", path); failed = 1; }
  29:         closedir(dir);
  30:         if (failed) return -1;
  31:     }
  32:     int rc = S_ISDIR(st.st_mode) ? rmdir(path) : unlink(path);
  33:     if (rc < 0) { error_path("cannot remove", path); return -1; }
  34:     return 0;
  35: }
  36: 
  37: /* I5, C1, C2: [-r] [-f] PATH...; refuse ".", ".." and "/". */
  38: int main(int argc, char **argv) {
  39:     init_program(argv[0]);
  40:     bool recursive = false, force = false;
  41:     int ch;
  42:     while ((ch = getopt(argc, argv, "rf")) != -1) {
  43:         if (ch == 'r') recursive = true;
  44:         else if (ch == 'f') force = true;
  45:         else { printf("Usage: %s [-rf] FILE...\n", program); return 1; }
  46:     }
  47:     if (optind == argc) { if (force) return 0; printf("Usage: %s [-rf] FILE...\n", program); return 1; }
  48:     int failed = 0;
  49:     struct stat root;
  50:     if (stat("/", &root) < 0) { error_path("cannot stat", "/"); return 1; }
  51:     for (int i = optind; i < argc; ++i) {
  52:         char *path = clean_path(argv[i]);
  53:         const char *base = base_name(path);
  54:         struct stat st;
  55:         bool dot = !strcmp(base, ".") || !strcmp(base, "..");
  56:         bool is_root = lstat(path, &st) == 0 && S_ISDIR(st.st_mode) &&
  57:                        st.st_dev == root.st_dev && st.st_ino == root.st_ino;
  58:         if (dot || is_root) {
  59:             fprintf(stderr, "%s: refusing to remove '%s'\n", program, argv[i]); failed = 1;
  60:         } else if (remove_tree(path, recursive, force) < 0) failed = 1;
  61:         free(path);
  62:     }
  63:     return failed;
  64: }
FILE touch.c
   1: #include "common.h"
   2: #include <errno.h>
   3: #include <fcntl.h>
   4: #include <stdio.h>
   5: #include <unistd.h>
   6: 
   7: /* I1: set access/modification time of PATH to now; create it empty if missing; never truncate. */
   8: static int touch(const char *path) {
   9:     if (utimensat(AT_FDCWD, path, NULL, 0) == 0) return 0;
  10:     if (errno != ENOENT) { error_path("cannot set timestamps", path); return -1; }
  11:     int fd = open(path, O_WRONLY | O_CREAT | O_NONBLOCK, 0666);
  12:     if (fd < 0) { error_path("cannot create", path); return -1; }
  13:     close(fd);
  14:     return 0;
  15: }
  16: 
  17: /* C1, C2: every operand, report and continue, usage when none. */
  18: int main(int argc, char **argv) {
  19:     init_program(argv[0]);
  20:     if (argc < 2) { printf("Usage: %s FILE...\n", program); return 1; }
  21:     int failed = 0;
  22:     for (int i = 1; i < argc; ++i)
  23:         if (touch(argv[i]) < 0) failed = 1;
  24:     return failed;
  25: }

FILE cat.c
   1: #include "common.h"
   2: #include <errno.h>
   3: #include <getopt.h>
   4: #include <stdio.h>
   5: #include <string.h>
   6: 
   7: static void usage(void) {
   8:     printf("Usage: %s [-nbsvETAet] [FILE...]\n"
   9:            "Concatenate files (or standard input for - or no files).\n"
  10:            "  -n number lines  -b number nonblank lines  -s squeeze blank lines\n"
  11:            "  -v show controls  -E show line ends  -T show tabs  -A all three\n", program);
  12: }
  13: int main(int argc, char **argv) {
  14:     init_program(argv[0]);
  15:     bool number = false, nonblank = false, squeeze = false;
  16:     bool visible = false, ends = false, tabs = false;
  17:     const struct option options[] = {{"help",0,NULL,1000},{0,0,0,0}};
  18:     int ch;
  19:     while ((ch = getopt_long(argc, argv, "nbsvETAetu", options, NULL)) != -1) {
  20:         switch (ch) {
  21:         case 'n': number = true; break;
  22:         case 'b': nonblank = true; break;
  23:         case 's': squeeze = true; break;
  24:         case 'A': visible = ends = tabs = true; break;
  25:         case 'e': visible = ends = true; break;
  26:         case 't': visible = tabs = true; break;
  27:         case 'v': visible = true; break;
  28:         case 'E': ends = true; break;
  29:         case 'T': tabs = true; break;
  30:         case 'u': break;
  31:         case 1000: usage(); return 0;
  32:         default: usage(); return 1;
  33:         }
  34:     }
  35:     unsigned long long line = 1;
  36:     bool start = true, previous_blank = false, pending_cr = false;
  37:     int failed = 0;
  38:     int count = argc - optind;
  39:     for (int i = 0; i < (count ? count : 1); ++i) {
  40:         const char *path = count ? argv[optind + i] : "-";
  41:         FILE *in = !strcmp(path, "-") ? stdin : fopen(path, "rb");
  42:         if (!in) { error_path("cannot open", path); failed = 1; continue; }
  43:         int c;
  44:         while ((c = fgetc(in)) != EOF) {
  45:             /* -E displays CRLF as ^M$, even without -v. Keep the CR pending
  46:                across file boundaries because input files form one stream. */
  47:             if (pending_cr) {
  48:                 if (c == '\n' || visible) fputs("^M", stdout);
  49:                 else putchar('\r');
  50:                 pending_cr = false;
  51:             }
  52:             if (start) {
  53:                 bool blank = c == '\n';
  54:                 if (squeeze && blank && previous_blank) continue;
  55:                 if ((nonblank && !blank) || (number && !nonblank)) printf("%6llu\t", line++);
  56:                 previous_blank = blank;
  57:                 start = false;
  58:             }
  59:             if (c == '\n') {
  60:                 if (ends) putchar('$');
  61:                 putchar('\n'); start = true;
  62:             } else if (c == '\r' && ends) {
  63:                 pending_cr = true;
  64:             } else if (c == '\t') {
  65:                 if (tabs) fputs("^I", stdout); else putchar(c);
  66:             } else {
  67:                 if (visible && c >= 128) { fputs("M-", stdout); c -= 128; }
  68:                 if (visible && (c < 32 || c == 127)) {
  69:                     putchar('^'); putchar(c == 127 ? '?' : c + 64);
  70:                 } else putchar(c);
  71:             }
  72:             if (ferror(stdout)) break;
  73:         }
  74:         if (ferror(in)) { error_path("cannot read", path); failed = 1; }
  75:         if (in != stdin && fclose(in) != 0) { error_path("cannot close", path); failed = 1; }
  76:         if (ferror(stdout)) break;
  77:     }
  78:     if (pending_cr) {
  79:         if (visible) fputs("^M", stdout); else putchar('\r');
  80:     }
  81:     if (fflush(stdout) == EOF || ferror(stdout)) { error_path("cannot write", "standard output"); failed = 1; }
  82:     return failed;
  83: }
