  45: bool confirm(const char *operation, const char *path) {
  46:     fprintf(stderr, "%s: %s '%s'? ", program, operation, path);
  47:     fflush(stderr);
  48:     int c = getchar(), first = c;
  49:     while (c != '\n' && c != EOF) c = getchar();
  50:     return first == 'y' || first == 'Y';
  51: }
  52: int parse_mode(const char *text, mode_t *mode) {
  53:     char *end;
  54:     errno = 0;
  55:     unsigned long n = strtoul(text, &end, 8);
  56:     if (!*text || *text == '-' || *end || errno || n > 07777) return -1;
  57:     *mode = (mode_t)n;
  58:     return 0;
