  61: /* lstat is deliberate: removing a directory symlink removes only the link. */
  62: int remove_tree(const char *path, bool recursive, bool dirs, bool force,
  63:                 bool interactive, bool verbose) {
  64:     struct stat st;
  65:     if (lstat(path, &st) < 0) {
  66:         if (force && errno == ENOENT) return 0;
  67:         error_path("cannot access", path); return -1;
  68:     }
  69:     if (S_ISDIR(st.st_mode)) {
  70:         if (!recursive && !dirs) {
  71:             errno = EISDIR; error_path("cannot remove", path); return -1;
  72:         }
  73:         if (recursive) {
  74:             if (interactive && !confirm("descend into directory", path)) return 1;
  75:             DIR *dir = opendir(path);
  76:             if (!dir) { error_path("cannot open directory", path); return -1; }
  77:             int failed = 0, skipped = 0;
  78:             struct dirent *entry;
  79:             for (;;) {
  80:                 errno = 0;
  81:                 entry = readdir(dir);
  82:                 if (!entry) {
  83:                     if (errno) { error_path("cannot read directory", path); failed = 1; }
  84:                     break;
  85:                 }
  86:                 if (!strcmp(entry->d_name, ".") || !strcmp(entry->d_name, "..")) continue;
  87:                 char *child = join_path(path, entry->d_name);
  88:                 int rc = remove_tree(child, true, dirs, force, interactive, verbose);
  89:                 if (rc < 0) failed = 1;
  90:                 if (rc > 0) skipped = 1;
  91:                 free(child);
  92:             }
