 105: /* Cross-filesystem mv fallback. Never traverse symbolic links. */
 106: int copy_tree(const char *source, const char *target) {
 107:     struct stat st;
 108:     if (lstat(source, &st) < 0) { error_path("cannot stat", source); return -1; }
 109:     if (S_ISLNK(st.st_mode)) {
 110:         size_t size = st.st_size > 0 ? (size_t)st.st_size + 1 : 256;
 111:         char *link;
 112:         for (;;) {
 113:             link = xmalloc(size + 1);
 114:             ssize_t n = readlink(source, link, size);
 115:             if (n < 0) { error_path("cannot read link", source); free(link); return -1; }
 116:             if ((size_t)n < size) { link[n] = '\0'; break; }
 117:             free(link); size *= 2;
 118:         }
 119:         int rc = symlink(link, target);
 120:         free(link);
 121:         if (rc < 0) { error_path("cannot create link", target); return -1; }
 122:         struct timespec times[2] = { st.st_atim, st.st_mtim };
 123:         if (utimensat(AT_FDCWD, target, times, AT_SYMLINK_NOFOLLOW) < 0) {
 124:             error_path("cannot set timestamps", target); return -1;
 125:         }
 126:         return 0;
 127:     }
 128:     if (S_ISDIR(st.st_mode)) {
 129:         if (mkdir(target, 0700) < 0) { error_path("cannot create directory", target); return -1; }
 130:         DIR *dir = opendir(source);
 131:         if (!dir) { error_path("cannot open directory", source); return -1; }
 132:         int failed = 0;
 133:         for (;;) {
 134:             errno = 0;
 135:             struct dirent *entry = readdir(dir);
 136:             if (!entry) {
 137:                 if (errno) { error_path("cannot read directory", source); failed = 1; }
 138:                 break;
 139:             }
 140:             if (!strcmp(entry->d_name, ".") || !strcmp(entry->d_name, "..")) continue;
 141:             char *src = join_path(source, entry->d_name);
 142:             char *dst = join_path(target, entry->d_name);
 143:             if (copy_tree(src, dst) < 0) failed = 1;
 144:             free(src); free(dst);
 145:             if (failed) break;
 146:         }
 147:         if (closedir(dir) < 0) { error_path("cannot close directory", source); failed = 1; }
 148:         if (failed) return -1;
 149:     } else if (S_ISREG(st.st_mode)) {
 150:         int in = open(source, O_RDONLY | O_NOFOLLOW);
 151:         if (in < 0) { error_path("cannot open", source); return -1; }
 152:         int out = open(target, O_WRONLY | O_CREAT | O_EXCL, 0600);
 153:         if (out < 0) { error_path("cannot create", target); close(in); return -1; }
 154:         char buffer[65536];
 155:         int failed = 0;
 156:         for (;;) {
 157:             ssize_t n = read(in, buffer, sizeof buffer);
 158:             if (n < 0 && errno == EINTR) continue;
 159:             if (n < 0) { error_path("cannot read", source); failed = 1; break; }
 160:             if (!n) break;
 161:             for (ssize_t offset = 0; offset < n;) {
 162:                 ssize_t written = write(out, buffer + offset, (size_t)(n - offset));
 163:                 if (written < 0 && errno == EINTR) continue;
 164:                 if (written <= 0) { error_path("cannot write", target); failed = 1; break; }
 165:                 offset += written;
 166:             }
 167:             if (failed) break;
 168:         }
 169:         if (close(in) < 0) { error_path("cannot close", source); failed = 1; }
 170:         if (close(out) < 0) { error_path("cannot close", target); failed = 1; }
 171:         if (failed) return -1;
 172:     } else {
 173:         errno = ENOTSUP; error_path("cannot copy special file", source); return -1;
 174:     }
 175:     if (chmod(target, st.st_mode & 07777) < 0) { error_path("cannot set mode", target); return -1; }
 176:     struct timespec times[2] = { st.st_atim, st.st_mtim };
 177:     if (utimensat(AT_FDCWD, target, times, 0) < 0) {
 178:         error_path("cannot set timestamps", target); return -1;
 179:     }
 180:     return 0;
 181: }
