 105:         n->kind = !strcmp(token, "-print") ? PRINT : (!strcmp(token, "-print0") ? PRINT0 : DELETE);
 106:         if (n->kind == DELETE) depth_first = true;
 107:     } else if (!strcmp(token, "-prune")) n->kind = PRUNE;
 108:     else if (!strcmp(token, "-depth")) depth_first = true;
 109:     else if (!strcmp(token, "-mindepth") || !strcmp(token, "-maxdepth")) {
