 119: static Node *parse_and(void) {
 120:     Node *n = parse_unary();
 121:     while (position < count && strcmp(args[position], ")") &&
 122:            strcmp(args[position], "-o") && strcmp(args[position], "-or")) {
 123:         if (!strcmp(args[position], "-a") || !strcmp(args[position], "-and")) ++position;
 124:         Node *right = parse_unary();
 125:         n = node(AND, n, right);
 126:     }
 127:     return n;
 128: }
 129: static Node *parse_or(void) {
