 149:     DIR *dir = opendir(path);
 150:     if (!dir) { error_path("cannot open directory", path); failed = 1; return false; }
 151:     bool result = true;
 152:     for (;;) {
 153:         errno = 0;
 154:         struct dirent *entry = readdir(dir);
 155:         if (!entry) {
 156:             if (errno) { error_path("cannot read directory", path); failed = 1; result = false; }
