 164: static bool evaluate(Node *n, const char *path, const struct stat *st, bool *prune) {
 165:     switch (n->kind) {
 166:     case YES: return true;
 167:     case AND: return evaluate(n->left, path, st, prune) && evaluate(n->right, path, st, prune);
 168:     case OR: return evaluate(n->left, path, st, prune) || evaluate(n->right, path, st, prune);
 169:     case NOT: return !evaluate(n->left, path, st, prune);
 170:     case NAME: case INAME: {
 171:         const char *base = !strcmp(path, "/") ? "/" : base_name(path);
 172:         return fnmatch(n->text, base, n->kind == INAME ? FNM_CASEFOLD : 0) == 0;
 173:     }
 174:     case PATH: return fnmatch(n->text, path, 0) == 0;
 175:     case TYPE:
 176:         switch (*n->text) {
 177:         case 'f': return S_ISREG(st->st_mode);
 178:         case 'd': return S_ISDIR(st->st_mode);
 179:         case 'l': return S_ISLNK(st->st_mode);
 180:         case 'b': return S_ISBLK(st->st_mode);
 181:         case 'c': return S_ISCHR(st->st_mode);
 182:         case 'p': return S_ISFIFO(st->st_mode);
 183:         case 's': return S_ISSOCK(st->st_mode);
 184:         }
 185:         return false;
 186:     case SIZE: return compare(n, st->st_size / n->unit + (st->st_size % n->unit != 0));
 187:     case MTIME: case MMIN:
 188:         return compare(n, (long long)floor(difftime(started, st->st_mtime) / (n->kind == MTIME ? 86400 : 60)));
 189:     case EMPTY: return empty(path, st);
 190:     case NEWER: return st->st_mtim.tv_sec > n->stamp.tv_sec ||
 191:                        (st->st_mtim.tv_sec == n->stamp.tv_sec && st->st_mtim.tv_nsec > n->stamp.tv_nsec);
