 193:         if (printf("%s%c", path, n->kind == PRINT ? '\n' : '\0') < 0) failed = 1;
 194:         return true;
 195:     case DELETE:
 196:         if ((S_ISDIR(st->st_mode) ? rmdir(path) : unlink(path)) < 0) {
 197:             error_path("cannot delete", path); failed = 1; return false;
 198:         }
 199:         return true;
 200:     case PRUNE: *prune = true; return true;
 201:     }
 202:     return false;
 203: }
 204: static void walk(const char *path, int depth, Node *expression) {
 205:     struct stat st;
 206:     if (lstat(path, &st) < 0) { error_path("cannot stat", path); failed = 1; return; }
 207:     bool prune = false;
 208:     if (!depth_first && depth >= min_depth) evaluate(expression, path, &st, &prune);
 209:     if (S_ISDIR(st.st_mode) && depth < max_depth && !prune) {
 210:         DIR *dir = opendir(path);
 211:         if (!dir) { error_path("cannot open directory", path); failed = 1; }
 212:         else {
 213:             for (;;) {
 214:                 errno = 0;
 215:                 struct dirent *entry = readdir(dir);
 216:                 if (!entry) {
 217:                     if (errno) { error_path("cannot read directory", path); failed = 1; }
 218:                     break;
 219:                 }
 220:                 if (!strcmp(entry->d_name, ".") || !strcmp(entry->d_name, "..")) continue;
 221:                 char *child = join_path(path, entry->d_name);
 222:                 walk(child, depth + 1, expression);
 223:                 free(child);
 224:             }
 225:             if (closedir(dir) < 0) { error_path("cannot close directory", path); failed = 1; }
 226:         }
 227:     }
 228:     if (depth_first && depth >= min_depth) evaluate(expression, path, &st, &prune);
 229: }
 230: int main(int argc, char **argv) {
 231:     init_program(argv[0]);
 232:     if (argc == 2 && !strcmp(argv[1], "--help")) { usage(); return 0; }
 233:     int first = 1;
 234:     if (first < argc && !strcmp(argv[first], "-P")) ++first;
 235:     if (first < argc && !strcmp(argv[first], "--")) ++first;
 236:     int end = first;
 237:     while (end < argc && argv[end][0] != '-' && strcmp(argv[end], "!") && strcmp(argv[end], "(")) ++end;
