 239:     Node *expression = position < count ? parse_or() : node(YES, NULL, NULL);
 240:     if (position != count) syntax("unexpected token", argv[position]);
 241:     if (!has_action) expression = node(AND, expression, node(PRINT, NULL, NULL));
 242:     started = time(NULL);
 243:     if (first == end) walk(".", 0, expression);
 244:     else for (int i = first; i < end; ++i) {
 245:         char *path = clean_path(argv[i]);
 246:         walk(path, 0, expression);
