  16: static int timestamp(const char *s, struct timespec *out) {
  17:     size_t length = strlen(s);
  18:     if (length != 12 && length != 15) return -1;
  19:     for (size_t i = 0; i < length; ++i) {
  20:         if (i == 12) { if (s[i] != '.') return -1; }
  21:         else if (s[i] < '0' || s[i] > '9') return -1;
  22:     }
  23:     struct tm tm = {0};
  24:     char *end = strptime(s, "%Y%m%d%H%M", &tm);
  25:     if (!end) return -1;
  26:     if (*end == '.') {
  27:         char *next;
  28:         long sec = strtol(end + 1, &next, 10);
  29:         if (next != end + 3 || *next || sec < 0 || sec > 59) return -1;
  30:         tm.tm_sec = (int)sec;
  31:     } else if (*end) return -1;
  32:     struct tm requested = tm;
  33:     tm.tm_isdst = -1;
  34:     time_t t = mktime(&tm);
  35:     if (tm.tm_year != requested.tm_year || tm.tm_mon != requested.tm_mon ||
  36:         tm.tm_mday != requested.tm_mday || tm.tm_hour != requested.tm_hour ||
  37:         tm.tm_min != requested.tm_min) return -1;
  38:     out->tv_sec = t; out->tv_nsec = 0;
  39:     return 0;
